import { Box } from '@mui/material'
import {
    MDXEditor, codeBlockPlugin, codeMirrorPlugin, diffSourcePlugin,
    headingsPlugin, imagePlugin, linkDialogPlugin, linkPlugin, listsPlugin, markdownShortcutPlugin, quotePlugin,
    tablePlugin, thematicBreakPlugin, toolbarPlugin,
    type MDXEditorMethods, type ViewMode,
} from '@mdxeditor/editor'
import '@mdxeditor/editor/style.css'
import {
    forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef,
    type FocusEvent, type ReactNode,
} from 'react'
import type { ActionPlaceholder } from '../../data/action_placeholders'
import { useProjectState } from '../hooks/use_project_state'
import { dialogService } from '../../services/dialog_service'
import { useAppTheme } from '../../theme/use_app_theme'
import { markdownDocumentHistoryPlugin } from './markdown_document_history_realm_plugin'
import type { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { MarkdownFormatToolbarControls } from './markdown_format_toolbar_controls'
import { markdownFileSearchPlugin } from './markdown_file_search_realm_plugin'
import { markdownLocalTextSearchPlugin } from './markdown_local_text_search_realm_plugin'
import { plainMarkdownPlugin } from './plain_markdown_realm_plugin'
import { markdownPlaceholderPlugin } from './markdown_placeholder_realm_plugin'
import { registerMarkdownEditorStage } from '../../services/project/markdown_editor_staging'
import { markdownPastePlugin } from './markdown_paste_realm_plugin'
import type { MarkdownImagePasteHandler } from './markdown_paste_cell'
import type {
    ActiveMarkdownDocumentChangedDetail,
    MarkdownBindingKind,
    MarkdownDataSource,
    MarkdownDocumentTarget,
} from './markdown_data_source'

const DEFAULT_CODE_LANGUAGE = ''
const CODE_BLOCK_LANGUAGES = { '': 'Plain text', js: 'JavaScript', ts: 'TypeScript', tsx: 'TSX', bash: 'Shell' }
const EMPTY_PLACEHOLDERS: readonly ActionPlaceholder[] = []
const EMPTY_REPOSITORY_FILES: readonly string[] = []

export interface MarkdownEditorHandle {
    flush(): boolean
    getMarkdown(): string
    setMarkdown(markdown: string): void
}

interface MarkdownEditorPresentationProps {
    diffMarkdown?: string
    flushOnBlur?: boolean
    /** Omit format toolbar entirely. */
    hideToolbar?: boolean
    imagePasteHandler?: MarkdownImagePasteHandler
    /** Set false when containing surface owns Ctrl+F behavior. */
    localTextSearch?: boolean
    overlayContainer?: HTMLElement | null
    placeholders?: readonly ActionPlaceholder[]
    readOnly?: boolean
    toolbarContents?: () => ReactNode
    viewMode?: ViewMode
}

interface MarkdownEditorDataSourceProps extends MarkdownEditorPresentationProps {
    binding: MarkdownBindingKind
    dataSource: MarkdownDataSource
    historyStore: MarkdownDocumentHistoryStore
    markdown?: never
    onChange?: never
    onDirtyChange?: never
    onLiveChange?: never
}

interface MarkdownEditorLocalProps extends MarkdownEditorPresentationProps {
    binding?: never
    dataSource?: never
    historyStore?: never
    markdown: string
    onChange: (markdown: string) => void
    onDirtyChange?: (dirty: boolean) => void
    onLiveChange?: (markdown: string) => void
}

type MarkdownEditorProps = MarkdownEditorDataSourceProps | MarkdownEditorLocalProps

interface MarkdownDocumentSnapshot {
    target: MarkdownDocumentTarget | null
    markdown: string
}

interface MarkdownProcessingError {
    error: string
}

function initialDocument(props: MarkdownEditorProps): MarkdownDocumentSnapshot {
    if (!props.dataSource) return { target: null, markdown: props.markdown }

    const target = props.dataSource.getActiveTarget(props.binding)
    return { target, markdown: target ? props.dataSource.getMarkdown(target) : '' }
}

/** Reusable MDXEditor surface with local-buffer and persisted data-source modes. */
export const MarkdownEditor = forwardRef<MarkdownEditorHandle, MarkdownEditorProps>(function MarkdownEditor(props, ref) {
    const {
        flushOnBlur = false,
        diffMarkdown,
        hideToolbar = false,
        imagePasteHandler,
        localTextSearch = true,
        overlayContainer,
        placeholders = EMPTY_PLACEHOLDERS,
        readOnly = false,
        toolbarContents: customToolbarContents,
        viewMode,
    } = props
    const dataSource = props.dataSource
    const binding = props.binding
    const historyStore = props.historyStore
    const { snapshot } = useProjectState()
    const repositoryFiles = snapshot?.repositoryFiles ?? EMPTY_REPOSITORY_FILES
    const initialDocumentRef = useRef<MarkdownDocumentSnapshot | null>(null)
    if (!initialDocumentRef.current) initialDocumentRef.current = initialDocument(props)
    const initialDocumentSnapshot = initialDocumentRef.current
    const { markdownContentSx, mode } = useAppTheme()
    const editorRef = useRef<MDXEditorMethods>(null)
    const activeTargetRef = useRef(initialDocumentSnapshot.target)
    const latestMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const lastEmittedMarkdownRef = useRef(initialDocumentSnapshot.markdown)
    const dirtyBaselineEstablishedRef = useRef(false)
    const missingEditorReportedRef = useRef(false)
    const replacingMarkdownRef = useRef(false)
    const onChangeRef = useRef(props.onChange)
    const onDirtyChangeRef = useRef(props.onDirtyChange)
    const onLiveChangeRef = useRef(props.onLiveChange)
    const applyPendingDocumentChangeRef = useRef<() => void>(() => undefined)
    onChangeRef.current = props.onChange
    onDirtyChangeRef.current = props.onDirtyChange
    onLiveChangeRef.current = props.onLiveChange

    const setDirty = useCallback((dirty: boolean) => {
        onDirtyChangeRef.current?.(dirty)
    }, [])

    const flush = useCallback(() => {
        if (latestMarkdownRef.current === lastEmittedMarkdownRef.current) return true

        const activeTarget = activeTargetRef.current
        if (dataSource && binding) {
            if (!activeTarget) return false
            const committed = dataSource.commit(binding, activeTarget, latestMarkdownRef.current)
            if (!committed) return false
        } else {
            onChangeRef.current?.(latestMarkdownRef.current)
        }
        lastEmittedMarkdownRef.current = latestMarkdownRef.current
        setDirty(false)
        queueMicrotask(() => applyPendingDocumentChangeRef.current())

        return true
    }, [binding, dataSource, setDirty])

    const prepareDocumentSwitch = useCallback((detail: ActiveMarkdownDocumentChangedDetail, nextMarkdown: string) => {
        if (detail.discard) lastEmittedMarkdownRef.current = latestMarkdownRef.current
        if (!flush()) return null

        const currentMarkdown = latestMarkdownRef.current
        activeTargetRef.current = detail.target
        latestMarkdownRef.current = nextMarkdown
        lastEmittedMarkdownRef.current = nextMarkdown
        setDirty(false)

        return currentMarkdown
    }, [flush, setDirty])

    const completeDocumentSwitch = useCallback((normalizedMarkdown: string) => {
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        setDirty(false)
    }, [setDirty])

    const getMarkdown = useCallback(() => editorRef.current?.getMarkdown() ?? latestMarkdownRef.current, [])
    const getTarget = useCallback(() => activeTargetRef.current, [])

    const replaceMarkdown = useCallback((markdown: string) => {
        replacingMarkdownRef.current = true
        editorRef.current?.setMarkdown(markdown)
        replacingMarkdownRef.current = false
    }, [])

    const setPendingDocumentChangeRetry = useCallback((retry: () => void) => {
        applyPendingDocumentChangeRef.current = retry
    }, [])

    const historyPluginConfig = useMemo(() => historyStore && binding && dataSource
        ? {
            binding,
            completeDocumentSwitch,
            dataSource,
            getTarget,
            getMarkdown,
            historyStore,
            prepareDocumentSwitch,
            replaceMarkdown,
            setPendingDocumentChangeRetry,
        }
        : null, [
        binding,
        completeDocumentSwitch,
        dataSource,
        getTarget,
        getMarkdown,
        historyStore,
        prepareDocumentSwitch,
        replaceMarkdown,
        setPendingDocumentChangeRetry,
    ])

    useEffect(() => {
        if (!editorRef.current) {
            if (!missingEditorReportedRef.current) {
                missingEditorReportedRef.current = true
                dialogService.error(new Error('Cannot baseline markdown before editor is mounted'), {fallbackMessage: 'Markdown editor could not be initialized'})
            }
            return
        }

        const normalizedMarkdown = editorRef.current.getMarkdown()
        latestMarkdownRef.current = normalizedMarkdown
        lastEmittedMarkdownRef.current = normalizedMarkdown
        dirtyBaselineEstablishedRef.current = true
    }, [])

    useEffect(() => {
        const unregister = registerMarkdownEditorStage(flush)

        return () => {
            unregister()
            flush()
        }
    }, [flush])

    useImperativeHandle(ref, () => ({
        flush,
        getMarkdown: () => latestMarkdownRef.current,
        setMarkdown: (markdown: string) => {
            replaceMarkdown(markdown)
            latestMarkdownRef.current = markdown
            lastEmittedMarkdownRef.current = markdown
            setDirty(false)
        },
    }), [flush, replaceMarkdown, setDirty])

    const handleEditorChange = useCallback((markdown: string) => {
        if (replacingMarkdownRef.current || latestMarkdownRef.current === markdown) return

        latestMarkdownRef.current = markdown
        if (!dirtyBaselineEstablishedRef.current) return
        setDirty(markdown !== lastEmittedMarkdownRef.current)
        onLiveChangeRef.current?.(markdown)
        const activeTarget = activeTargetRef.current
        if (dataSource && binding && activeTarget) dataSource.edit(binding, activeTarget, markdown)
    }, [binding, dataSource, setDirty])

    const handleEditorError = useCallback(({ error }: MarkdownProcessingError) => {
        dialogService.error(new Error(error), { fallbackMessage: 'Markdown could not be parsed' })
    }, [])

    const handleBlur = (event: FocusEvent<HTMLDivElement>) => {
        if (!flushOnBlur || event.currentTarget.contains(event.relatedTarget)) return
        flush()
    }

    const insertMarkdown = useCallback((markdown: string) => {
        editorRef.current?.insertMarkdown(markdown)
    }, [])

    const getSelectionMarkdown = useCallback(() => editorRef.current?.getSelectionMarkdown() ?? '', [])

    const defaultToolbarContents = useCallback(
        () => <MarkdownFormatToolbarControls overlayContainer={overlayContainer} placeholders={placeholders} />,
        [overlayContainer, placeholders],
    )
    const toolbarContents = customToolbarContents ?? defaultToolbarContents
    const editorSx = {
        ...markdownContentSx,
        '& .mdxeditor-toolbar': { bgcolor: 'background.paper', position: 'sticky', top: 0, zIndex: 1 },
    }
    const historyPlugin = historyPluginConfig ? markdownDocumentHistoryPlugin(historyPluginConfig) : null
    const plugins = [
        headingsPlugin(),
        listsPlugin(),
        quotePlugin(),
        thematicBreakPlugin(),
        linkPlugin(),
        linkDialogPlugin(),
        imagePlugin(),
        tablePlugin(),
        codeBlockPlugin({ defaultCodeBlockLanguage: DEFAULT_CODE_LANGUAGE }),
        codeMirrorPlugin({ codeBlockLanguages: CODE_BLOCK_LANGUAGES }),
        markdownShortcutPlugin(),
        plainMarkdownPlugin(),
        ...(viewMode ? [diffSourcePlugin({ diffMarkdown: diffMarkdown ?? '', viewMode })] : []),
        ...(hideToolbar ? [] : [toolbarPlugin({ toolbarContents })]),
        markdownPlaceholderPlugin({ overlayContainer, placeholders }),
        markdownFileSearchPlugin({ overlayContainer, repositoryFiles }),
        ...(localTextSearch ? [markdownLocalTextSearchPlugin({ overlayContainer })] : []),
        markdownPastePlugin({ getSelectionMarkdown, imagePasteHandler, insertMarkdown, readOnly }),
        ...(historyPlugin ? [historyPlugin] : []),
    ]

    return (
        <Box data-sticky-toolbar onBlur={handleBlur} sx={editorSx}>
            <MDXEditor
                className={mode === 'dark' ? 'dark-theme' : 'light-theme'}
                contentEditableClassName="mdxeditor-content"
                markdown={initialDocumentSnapshot.markdown}
                onChange={handleEditorChange}
                onError={handleEditorError}
                overlayContainer={overlayContainer}
                plugins={plugins}
                readOnly={readOnly}
                ref={editorRef}
                suppressHtmlProcessing
                suppressSharedHistory={!!historyStore}
            />
        </Box>
    )
})

import { act, cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { createRef, type ReactNode } from 'react'
import { AppThemeContext } from '../../theme/theme_context'
import { AppThemeProvider } from '../../theme/theme_provider'
import { ACTION_PROMPT_PLACEHOLDERS } from '../../data/action_placeholders'
import { dialogService } from '../../services/dialog_service'
import { THEME_MODE_STORAGE_KEY } from '../../theme/use_theme_settings'
import { MARKDOWN_STYLE_PRESETS } from '../../theme/theme_config'
import { useAppTheme } from '../../theme/use_app_theme'
import { MarkdownEditor, type MarkdownEditorHandle } from './markdown_editor'
import { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import { stageMarkdownEditors } from '../../services/project/markdown_editor_staging'
import { buildMarkdownContentSx } from './markdown_style_sx'
import {
    MarkdownDataSourceBase,
    type MarkdownBindingKind,
    type MarkdownDataSource,
    type MarkdownDocumentTarget,
} from './markdown_data_source'
import type { CardOpenDocument } from '../../services/open_files_service'

class TestMarkdownDataSource extends MarkdownDataSourceBase {
    readonly commit = vi.fn<MarkdownDataSource['commit']>(() => true)
    readonly edit = vi.fn()
    private readonly markdownByTarget = new Map<MarkdownDocumentTarget, string>()
    private readonly targets = new Map<string, MarkdownDocumentTarget>()

    getMarkdown(target: MarkdownDocumentTarget) {
        const markdown = this.markdownByTarget.get(target)
        if (markdown === undefined) throw new Error('Unknown test document')
        return markdown
    }

    select(binding: MarkdownBindingKind, identity: string, markdown: string) {
        const target = this.target(identity)
        this.markdownByTarget.set(target, markdown)
        this.setActiveTarget(binding, target)
        return target
    }

    replace(target: MarkdownDocumentTarget, markdown: string, originBinding: MarkdownBindingKind | null = null) {
        this.markdownByTarget.set(target, markdown)
        this.dispatchMarkdownReplaced({ originBinding, target })
    }

    target(identity: string) {
        const existing = this.targets.get(identity)
        if (existing) return existing
        const document = Object.assign(new EventTarget(), { kind: 'card' as const }) as CardOpenDocument
        const target: MarkdownDocumentTarget = { document }
        this.targets.set(identity, target)
        return target
    }
}

function renderEditor(markdown = '') {
    return render(
        <AppThemeProvider>
            <MarkdownEditor markdown={markdown} onChange={vi.fn()} />
        </AppThemeProvider>,
    )
}

function selectText(textbox: HTMLTextAreaElement, start: number, end: number) {
    textbox.setSelectionRange(start, end)
    fireEvent.select(textbox)
}

function clipboardData(initialData: Record<string, string> = {}) {
    const data = new Map(Object.entries(initialData))
    return {
        getData: (type: string) => data.get(type) ?? '',
        setData: (type: string, value: string) => data.set(type, value),
        value: (type: string) => data.get(type) ?? '',
    }
}

function imageClipboardData(file: File, plainText = '') {
    return {
        getData: (type: string) => type === 'text/plain' ? plainText : '',
        items: [{ getAsFile: () => file, kind: 'file', type: file.type }],
    }
}

function MarkdownEditorWithStyleControl() {
    const { setMarkdownStyle } = useAppTheme()
    const handleSetSerif = () => {
        setMarkdownStyle('serif')
    }

    return (
        <>
            <button onClick={handleSetSerif} type="button">Serif</button>
            <MarkdownEditor markdown="" onChange={vi.fn()} />
        </>
    )
}

function MarkdownContentSxOverride({ children }: { children: ReactNode }) {
    const theme = useAppTheme()
    const value = { ...theme, markdownContentSx: { paddingTop: '37px' } }

    return <AppThemeContext.Provider value={value}>{children}</AppThemeContext.Provider>
}

describe('MarkdownEditor', () => {
    afterEach(() => {
        cleanup()
        window.localStorage.clear()
    })

    it('renders the editing surface seeded with the markdown value', () => {
        renderEditor('# Title\n\nBody')

        expect(screen.getByRole('textbox')).toHaveValue('# Title\n\nBody')
    })

    it('disables MDX and HTML processing', () => {
        renderEditor()

        expect(document.querySelector('[data-html-processing-suppressed="true"]')).not.toBeNull()
    })

    it('reports Markdown parser errors through the dialog service', () => {
        const reportError = vi.spyOn(dialogService, 'error')
        renderEditor()

        fireEvent.click(screen.getByTestId('emit-markdown-error'))

        expect(reportError).toHaveBeenCalledExactlyOnceWith(
            new Error('Invalid Markdown'),
            { fallbackMessage: 'Markdown could not be parsed' },
        )
        reportError.mockRestore()
    })

    it('imports plain clipboard text as markdown', () => {
        const markdown = '# Title\n\n- Item\n\n[Link](https://example.com)\n\n```js\nconst value = 1;\n```'
        renderEditor()

        const pasteHandled = fireEvent.paste(screen.getByRole('textbox'), {clipboardData: {getData: (type: string) => type === 'text/plain' ? markdown : ''}})

        expect(pasteHandled).toBe(false)
        expect(screen.getByRole('textbox')).toHaveValue(markdown)
    })

    it('prefers explicit markdown clipboard content over plain text', () => {
        renderEditor()

        fireEvent.paste(screen.getByRole('textbox'), {clipboardData: {getData: (type: string) => type === 'text/markdown' ? '**Markdown**' : 'Plain text'}})

        expect(screen.getByRole('textbox')).toHaveValue('**Markdown**')
    })

    it('leaves non-text clipboard data to the editor', () => {
        renderEditor()

        const pasteHandled = fireEvent.paste(screen.getByRole('textbox'), {clipboardData: { getData: () => '' }})

        expect(pasteHandled).toBe(true)
        expect(screen.getByRole('textbox')).toHaveValue('')
    })

    it('routes a binary image before clipboard text and inserts after the handler completes', async () => {
        const file = new File(['image'], 'clipboard.png', { type: 'image/png' })
        const imagePasteHandler = vi.fn(async (_file: File, insertMarkdown: (markdown: string) => void) => {
            insertMarkdown('![pasted image](<saved.png>)')
        })
        render(
            <AppThemeProvider>
                <MarkdownEditor imagePasteHandler={imagePasteHandler} markdown="before " onChange={vi.fn()} />
            </AppThemeProvider>,
        )

        const pasteHandled = fireEvent.paste(
            screen.getByRole('textbox'),
            { clipboardData: imageClipboardData(file, 'fallback text') },
        )

        expect(pasteHandled).toBe(false)
        expect(imagePasteHandler).toHaveBeenCalledWith(file, expect.any(Function))
        await waitFor(() => expect(screen.getByRole('textbox')).toHaveValue('![pasted image](<saved.png>)before'))
    })

    it('leaves image clipboard items unchanged when no image handler is supplied', () => {
        const file = new File(['image'], 'clipboard.png', { type: 'image/png' })
        renderEditor()

        const pasteHandled = fireEvent.paste(
            screen.getByRole('textbox'),
            { clipboardData: imageClipboardData(file) },
        )

        expect(pasteHandled).toBe(true)
        expect(screen.getByRole('textbox')).toHaveValue('')
    })

    it('does not invoke an image handler in a read-only editor', () => {
        const file = new File(['image'], 'clipboard.png', { type: 'image/png' })
        const imagePasteHandler = vi.fn()
        render(
            <AppThemeProvider>
                <MarkdownEditor imagePasteHandler={imagePasteHandler} markdown="locked" onChange={vi.fn()} readOnly />
            </AppThemeProvider>,
        )

        fireEvent.paste(screen.getByRole('textbox'), { clipboardData: imageClipboardData(file) })

        expect(imagePasteHandler).not.toHaveBeenCalled()
        expect(screen.getByRole('textbox')).toHaveValue('locked')
    })

    it('reports failed image persistence without inserting Markdown', async () => {
        const file = new File(['image'], 'clipboard.png', { type: 'image/png' })
        const persistenceError = new Error('save failed')
        const reportError = vi.spyOn(dialogService, 'error')
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    imagePasteHandler={vi.fn(async () => { throw persistenceError })}
                    markdown=""
                    onChange={vi.fn()}
                />
            </AppThemeProvider>,
        )

        fireEvent.paste(screen.getByRole('textbox'), { clipboardData: imageClipboardData(file) })

        await waitFor(() => expect(reportError).toHaveBeenCalledWith(
            persistenceError,
            { fallbackMessage: 'Clipboard image could not be pasted' },
        ))
        expect(screen.getByRole('textbox')).toHaveValue('')
    })

    it('copies selected formatted content as Markdown in both text formats', () => {
        const markdown = '# Title\n\n**Bold** and [Link](https://example.com)\n\n- Item\n\n`code`'
        renderEditor(markdown)
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        const clipboard = clipboardData()
        selectText(textbox, 0, markdown.length)

        const copyHandled = fireEvent.copy(textbox, { clipboardData: clipboard })

        expect(copyHandled).toBe(false)
        expect(clipboard.value('text/markdown')).toBe(markdown)
        expect(clipboard.value('text/plain')).toBe(markdown)
    })

    it('copies only rendered text with Ctrl+Shift+C', () => {
        const markdown = '**Bold** and [Link](https://example.com)'
        renderEditor(markdown)
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        const clipboard = clipboardData()
        selectText(textbox, 0, markdown.length)

        fireEvent.keyDown(textbox, { ctrlKey: true, key: 'c', shiftKey: true })
        fireEvent.copy(textbox, { clipboardData: clipboard })

        expect(clipboard.value('text/plain')).toBe('Bold and Link')
        expect(clipboard.value('text/markdown')).toBe('')
    })

    it('preserves formatting around a partial copied selection', () => {
        renderEditor('Before **bold text** after')
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        const clipboard = clipboardData()
        selectText(textbox, 9, 13)

        fireEvent.copy(textbox, { clipboardData: clipboard })

        expect(clipboard.value('text/markdown')).toBe('**bold**')
        expect(clipboard.value('text/plain')).toBe('**bold**')
    })

    it('leaves clipboard data unchanged for a collapsed selection', () => {
        renderEditor('Text')
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        const clipboard = clipboardData({ 'text/plain': 'existing' })
        selectText(textbox, 2, 2)

        const copyHandled = fireEvent.copy(textbox, { clipboardData: clipboard })

        expect(copyHandled).toBe(true)
        expect(clipboard.value('text/plain')).toBe('existing')
    })

    it('replaces the current selection when pasting Markdown', () => {
        renderEditor('before old after')
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        selectText(textbox, 7, 10)

        fireEvent.paste(textbox, { clipboardData: clipboardData({ 'text/plain': '**new**' }) })

        expect(textbox).toHaveValue('before **new** after')
    })

    it('inserts plain clipboard text literally with Ctrl+Shift+V', () => {
        renderEditor('old')
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        selectText(textbox, 0, 3)

        fireEvent.keyDown(textbox, { ctrlKey: true, key: 'v', shiftKey: true })
        fireEvent.paste(textbox, { clipboardData: clipboardData({ 'text/plain': '**bold**' }) })

        expect(textbox).toHaveValue('**bold**')
    })

    it('consumes shifted copy intent once', () => {
        const markdown = '**Bold**'
        renderEditor(markdown)
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        selectText(textbox, 0, markdown.length)
        const textClipboard = clipboardData()
        const markdownClipboard = clipboardData()

        fireEvent.keyDown(textbox, { ctrlKey: true, key: 'c', shiftKey: true })
        fireEvent.copy(textbox, { clipboardData: textClipboard })
        fireEvent.copy(textbox, { clipboardData: markdownClipboard })

        expect(textClipboard.value('text/plain')).toBe('Bold')
        expect(markdownClipboard.value('text/markdown')).toBe(markdown)
    })

    it('clears shifted paste intent when no matching clipboard event follows', async () => {
        renderEditor('')
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement

        fireEvent.keyDown(textbox, { ctrlKey: true, key: 'v', shiftKey: true })
        await act(async () => new Promise((resolve) => setTimeout(resolve, 0)))
        fireEvent.paste(textbox, { clipboardData: clipboardData({ 'text/plain': '**bold**' }) })

        expect(textbox).toHaveValue('**bold**')
    })

    it('allows copy but prevents paste changes in read-only editors', () => {
        const markdown = '**locked**'
        render(
            <AppThemeProvider>
                <MarkdownEditor markdown={markdown} onChange={vi.fn()} readOnly />
            </AppThemeProvider>,
        )
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        const clipboard = clipboardData()
        selectText(textbox, 0, markdown.length)

        fireEvent.copy(textbox, { clipboardData: clipboard })
        fireEvent.paste(textbox, { clipboardData: clipboardData({ 'text/plain': 'changed' }) })

        expect(clipboard.value('text/markdown')).toBe(markdown)
        expect(textbox).toHaveValue(markdown)
    })

    it('reports clipboard write failures without preventing default copy', () => {
        const reportError = vi.spyOn(dialogService, 'error')
        renderEditor('Text')
        const textbox = screen.getByRole('textbox') as HTMLTextAreaElement
        selectText(textbox, 0, 4)
        const clipboard = {
            getData: () => '',
            setData: () => { throw new Error('Clipboard unavailable') },
        }

        const copyHandled = fireEvent.copy(textbox, { clipboardData: clipboard })

        expect(copyHandled).toBe(true)
        expect(reportError).toHaveBeenCalledWith(
